solution:
#include <stdio.h>

int main(void) {
    int year;
    scanf("%d", &year);
    if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
        printf("LEAP\n");
    } else {
        printf("COMMON\n");
    }
    return 0;
}
